DO $$
DECLARE
    bad      INTEGER;
    moved    INTEGER := 0;
    expected INTEGER := 51;
    r        RECORD;
BEGIN
    -- guard 1: every site is a curated site that still exists
    SELECT count(*) INTO bad FROM _coord_plan p LEFT JOIN unified_sites u ON u.id = p.site_id
     WHERE u.id IS NULL OR u.source_id <> 'ancient_nerds';
    IF bad > 0 THEN
        RAISE EXCEPTION 'owner-case coordinates: % row(s) are not curated sites', bad;
    END IF;
    -- guard 2: every site moves as a whole - geom, lat and lon, nothing else
    SELECT count(*) INTO bad FROM (
        SELECT site_id FROM _coord_plan GROUP BY site_id
        HAVING array_agg(column_name ORDER BY column_name) <> ARRAY['geom', 'lat', 'lon']
    ) x;
    IF bad > 0 THEN
        RAISE EXCEPTION 'owner-case coordinates: % site(s) do not move geom, lat and lon together', bad;
    END IF;
    -- guard 3: every row still holds the planned old value, compared in the column's type
    SELECT count(*) INTO bad FROM _coord_plan p JOIN unified_sites u ON u.id = p.site_id
     WHERE (p.column_name = 'lat' AND u.lat IS DISTINCT FROM p.old_value::double precision)
        OR (p.column_name = 'lon' AND u.lon IS DISTINCT FROM p.old_value::double precision)
        OR (p.column_name = 'geom' AND u.geom IS DISTINCT FROM p.old_value::geometry);
    IF bad > 0 THEN
        RAISE EXCEPTION 'owner-case coordinates: % row(s) no longer hold the planned old value', bad;
    END IF;
    -- guard 4: the planned geom is the planned point
    SELECT count(*) INTO bad FROM _coord_plan g
      JOIN _coord_plan a ON a.site_id = g.site_id AND a.column_name = 'lat'
      JOIN _coord_plan o ON o.site_id = g.site_id AND o.column_name = 'lon'
     WHERE g.column_name = 'geom' AND g.new_value::geometry IS DISTINCT FROM
           ST_SetSRID(ST_MakePoint(o.new_value::double precision,
                                   a.new_value::double precision), 4326);
    IF bad > 0 THEN
        RAISE EXCEPTION 'owner-case coordinates: % planned geom value(s) are not the planned point', bad;
    END IF;
    -- the writes: apply_remediation_change raises unless exactly one row matched
    FOR r IN SELECT * FROM _coord_plan ORDER BY site_id, column_name LOOP
        moved := moved + apply_remediation_change(
            'unified_sites', r.column_name, 'id', r.site_id::text,
            r.old_value, r.new_value,
            'B1B2/coordinates', '2026-09-23_owner-case-coordinates-rollback', r.change_key, 'two_source', r.evidence, r.site_id);
    END LOOP;
    IF moved <> expected THEN
        RAISE EXCEPTION 'owner-case coordinates: % row(s) changed, % planned', moved, expected;
    END IF;
    -- invariant 1: every site holds the new point, and a geom that is that point
    SELECT count(*) INTO bad FROM _coord_plan p JOIN unified_sites u ON u.id = p.site_id
     WHERE (p.column_name = 'lat' AND u.lat IS DISTINCT FROM p.new_value::double precision)
        OR (p.column_name = 'lon' AND u.lon IS DISTINCT FROM p.new_value::double precision)
        OR (p.column_name = 'geom' AND u.geom IS DISTINCT FROM
            ST_SetSRID(ST_MakePoint(u.lon, u.lat), 4326));
    IF bad > 0 THEN
        RAISE EXCEPTION 'owner-case coordinates: % row(s) do not hold the new point', bad;
    END IF;
    -- invariant 2: the journal and the plan agree in both directions
    SELECT count(*) INTO bad FROM _coord_plan p LEFT JOIN remediation_change_log l
        ON l.run_stamp = '2026-09-23_owner-case-coordinates-rollback' AND l.change_key = p.change_key
       AND l.table_name = 'unified_sites' AND l.column_name = p.column_name
       AND l.row_pk = p.site_id::text
       AND l.old_value = p.old_value AND l.new_value = p.new_value
     WHERE l.id IS NULL;
    IF bad > 0 THEN
        RAISE EXCEPTION 'owner-case coordinates: % row(s) have no matching journal row', bad;
    END IF;
    SELECT count(*) INTO bad FROM remediation_change_log l
     WHERE l.run_stamp = '2026-09-23_owner-case-coordinates-rollback'
       AND NOT EXISTS (SELECT 1 FROM _coord_plan p WHERE p.change_key = l.change_key);
    IF bad > 0 THEN
        RAISE EXCEPTION 'owner-case coordinates: this stamp journalled % row(s) outside the plan', bad;
    END IF;
    RAISE NOTICE 'owner-case coordinates: % row(s) changed and journalled', moved;
END $$;

COMMIT;

SELECT 'journal rows for this stamp' AS metric, count(*)::text AS value
  FROM remediation_change_log WHERE run_stamp = '2026-09-23_owner-case-coordinates-rollback';
